from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient
app = FastAPI()
def get_color():
    return 'blue'
@app.get('/color')
def color(value=Depends(get_color)):
    return {'color': value}
def test_color():
    return 'green'
with TestClient(app) as client:
    print(client.get('/color').json())
    app.dependency_overrides[get_color] = test_color
    try:
        print(client.get('/color').json())
    finally:
        app.dependency_overrides.clear()

